import { NotFoundError, ValidationError } from '../domain/errors';
import { ProjectRepository } from '../domain/ProjectRepository';
import { Task } from '../domain/Task';
import { TaskRepository } from '../domain/TaskRepository';
import { UserRepository } from '../domain/UserRepository';
import { TaskDto, toTaskDto } from './dto';
import { IdGenerator } from './IdGenerator';

export interface CreateTaskInput {
  projectId: string;
  title?: string;
  description?: string;
  dueDate?: string;
  status?: string;
  assigneeId?: string;
}

export class CreateTaskUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
  ) {}

  async execute(input: CreateTaskInput): Promise<TaskDto> {
    if (!(await this.projects.findById(input.projectId))) {
      throw new NotFoundError('Project', input.projectId);
    }
    if (input.assigneeId !== undefined && !(await this.users.findById(input.assigneeId))) {
      throw new NotFoundError('User', input.assigneeId);
    }
    const task = Task.create({
      id: this.ids.next(),
      projectId: input.projectId,
      title: input.title,
      description: input.description,
      dueDate: parseDueDate(input.dueDate),
      status: input.status,
      assigneeId: input.assigneeId,
    });
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

function parseDueDate(value: string | undefined): Date | undefined {
  if (value === undefined) {
    return undefined;
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new ValidationError('Task due date is invalid');
  }
  return date;
}

